84	void ChromSweep::ScanCache() {
85	    list<BED>::iterator c = _cache.begin();
86	    while (c != _cache.end())
87	    {
88	        if ((_curr_qy.chrom == c->chrom) && !(after(_curr_qy, *c))) {
89	            if (IsValidHit(_curr_qy, *c)) {
90	                _hits.push_back(*c);
91	            }
92	            ++c;
93	        }
94	        else {
95	            c = _cache.erase(c);
96	        }
97	    }
98	}
