424	bool NewChromSweep::verifyChromOrderMismatch(const string & chrom, const string &prevChrom, int skipFile) {
425	    //for every file except the one being checked,
426	    //find the current and previous chrom. If a given file
427	    //is missing either, skip it and go on. If it has both,
428	    //and the curr has a lower order num than the prev, return true.
429	
430	    //if that never happens, return false.
431	    for (int i=0; i < _numFiles; i++) {
432	        if (i == skipFile) continue;
433	        const _orderTrackType *track = _fileTracks[i];
434	        _orderTrackType::const_iterator iter = track->find(chrom);
435	        if (iter == track->end()) continue; //this file does not contain the curr chrom
436	        int currOrder = iter->second;
437	        iter = track->find(prevChrom);
438	        if (iter == track->end()) continue; //this file does not contain the prevChrom.
439	        int prevOrder = iter->second;
440	
441	        if (currOrder < prevOrder) return true;
442	    }
443	    return false;
444	}
445	
446	void NewChromSweep::testThatAllDbChromsExistInQuery()
447	{
448	    if (_context->hasGenomeFile() || !_lexicoDisproven) return;
449	
450	    int queryIdx = _context->getQueryFileIdx();
451	    //get the query file track. Then check that every chrom in every db exists in it.
452	    const _orderTrackType *qTrack = _fileTracks[queryIdx];
453	
454	    for (int i=0; i < _numFiles; i++) {
455	        if (i == queryIdx) continue;
456	        const _orderTrackType *dbTrack = _fileTracks[i];
457	        for (_orderTrackType::const_iterator iter = dbTrack->begin(); iter != dbTrack->end(); iter++) {
458	            const string &chrom = iter->first;
459	            if (qTrack->find(chrom) == qTrack->end()
460	                && !chrom.empty())  // don't raise an error if the chrom is unknown (e.g., unmapped BAM)
461	            {
462	                fprintf(stderr, "ERROR: Database file %s contains chromosome %s, but the query file does not.\n",
463	                        _context->getInputFileName(i).c_str(), chrom.c_str());
464	                fprintf(stderr, "       Please rerun with the -g option for a genome file.\n       See documentation for details.\n");
465	                exit(1);
466	            }
467	        }
468	    }
469	}
470	
471	
472	bool NewChromSweep::testLexicoQueryAfterDb(const Record *queryRec, const Record *dbRec)
473	{
474	    if (_lexicoDisproven) return false;
475	
476	    bool queryGreater = queryRec->getChrName() > dbRec->getChrName();
477	    if (!_lexicoAssumed && queryGreater) {
478	        _lexicoAssumed = true;
479	        _lexicoAssumedFileIdx = dbRec->getFileIdx();
480	        _lexicoAssumedChromName = dbRec->getChrName();
481	    }
482	    return queryGreater;
483	}
