void NewChromSweep::closeOut(bool testChromOrderVal) {
    if (_testLastQueryRec) {
        testChromOrder(_currQueryRec);
    }
    bool should_test_last_rec = true;
    while (!_queryFRM->eof()) {
        nextRecord(true);
        testChromOrder(_currQueryRec);
        _queryFRM->deleteRecord(_currQueryRec);
		should_test_last_rec = false;
    }
    if (testChromOrderVal) {
        if(should_test_last_rec) testChromOrder(_currQueryRec);
    }
    // Always consume the remaining database records so that the summary
    // state (total records and total record length) reflects the complete
    // database file, not just the subset that sweep happened to use. This is
    // required by callers such as fisher, which build a statistical summary
    // from the full interval sets. Only the optional chromosome sort-order
    // checks are gated on testChromOrderVal.
    for (int i=0; i < _numDBs; i++) {
        while (!_dbFRMs[i]->eof()) {
            if (testChromOrderVal) testChromOrder(_currDbRecs[i]);
            _dbFRMs[i]->deleteRecord(_currDbRecs[i]);
            nextRecord(false, i);
        }
        if (testChromOrderVal) testChromOrder(_currDbRecs[i]);
    }
}

